        Contains(scanner, "plugin_security_managed_symbols", "managed metadata symbols are persisted for later call/diff analysis");
        Contains(scanner, "process.execute", "high-confidence metadata references can strengthen permission candidates without claiming runtime execution");
        Contains(scanner, "_decode_cil_calls", "compiled CIL method bodies are decoded without loading assemblies");
        Contains(scanner, "callvirt", "CIL virtual method call sites are recorded");
        Contains(scanner, "newobj", "CIL object-construction call sites are supported");
        Contains(scanner, "ldftn", "CIL function-pointer targets are recorded");
        Contains(scanner, "sourceMethodToken", "call-site evidence retains the containing compiled method token");
