        Contains(scanner, "targetMethodToken", "local compiled calls retain the exact MethodDef target token for graph traversal");
        Contains(scanner, "plugin_security_managed_reachability", "bounded local method reachability is persisted separately from call-site evidence");
        Contains(scanner, "MAX_MANAGED_REACHABILITY_DEPTH", "local graph traversal is depth bounded for hostile artifacts");
        Contains(scanner, "callback-name", "probable event callbacks can seed explicitly-labeled heuristic roots");
        Contains(scanner, "VeryHigh", "compiled call-site evidence strengthens permission confidence without claiming runtime reachability");
        Contains(scanner, "but it still does not prove that a runtime branch actually", "reachability evidence preserves the static-analysis runtime boundary");
